use volterra_core::ActiveNematicParams3D;
use volterra_core::{QField3D, ScalarField3D};
use volterra_fd::runner_3d::run_bech_3d;

fn fixture() -> (QField3D, ScalarField3D, ActiveNematicParams3D) {
    let mut p = ActiveNematicParams3D::default_test();
    p.nx = 8;
    p.ny = 8;
    p.nz = 8;
    p.noise_amp = 0.01;
    let q = QField3D::random_perturbation(p.nx, p.ny, p.nz, p.dx, 0.001, 42);
    let phi = ScalarField3D::uniform(p.nx, p.ny, p.nz, p.dx, 0.3);
    (q, phi, p)
}

fn flatten_q(q: &QField3D) -> Vec<f64> {
    q.q.iter().flat_map(|arr| arr.iter().copied()).collect()
}

#[test]
fn bech_3d_matches_captured_oracle_bit_for_bit() {
    let (q0, phi0, p) = fixture();
    let tmp = std::env::temp_dir().join("volterra_golden_bech3d_oracle");
    std::fs::create_dir_all(&tmp).unwrap();
    let (qf, phif, stats) = run_bech_3d(&q0, &phi0, &p, 4, 2, &tmp, false);

    let q_field = flatten_q(&qf);
    let phi_flat: Vec<f64> = phif.phi.to_vec();

    // Q field
    assert_eq!(
        q_field.len(),
        ORACLE_Q_FIELD.len(),
        "q field length mismatch"
    );
    for (i, (a, b)) in q_field.iter().zip(ORACLE_Q_FIELD.iter()).enumerate() {
        assert_eq!(a.to_bits(), b.to_bits(), "q field drifted at index {i}");
    }

    // phi field
    assert_eq!(
        phi_flat.len(),
        ORACLE_PHI_FLAT.len(),
        "phi field length mismatch"
    );
    for (i, (a, b)) in phi_flat.iter().zip(ORACLE_PHI_FLAT.iter()).enumerate() {
        assert_eq!(a.to_bits(), b.to_bits(), "phi field drifted at index {i}");
    }

    // stats
    assert_eq!(stats.len(), 2, "expected 2 snapshots");
    let oracle_mean_s = [0.0045597918877291225_f64, 0.006062225733977352_f64];
    let oracle_biax = [0.003108991444229705_f64, 0.004101240175093023_f64];
    let oracle_mean_phi = [0.3_f64, 0.2999999999999998_f64];
    for (i, s) in stats.iter().enumerate() {
        assert_eq!(
            s.mean_s.to_bits(),
            oracle_mean_s[i].to_bits(),
            "mean_s drifted at snapshot {i}"
        );
        assert_eq!(
            s.biaxiality_p.to_bits(),
            oracle_biax[i].to_bits(),
            "biaxiality_p drifted at snapshot {i}"
        );
        assert_eq!(
            s.mean_phi.to_bits(),
            oracle_mean_phi[i].to_bits(),
            "mean_phi drifted at snapshot {i}"
        );
    }

    // npy bytes (step 1 = q_000001, phi_000001, vel_000001)
    let q_npy_bytes = std::fs::read(tmp.join("q_000001.npy")).expect("q npy must exist");
    assert_eq!(
        q_npy_bytes.len(),
        ORACLE_Q_NPY_BYTES.len(),
        "q npy length mismatch"
    );
    for (i, (a, b)) in q_npy_bytes
        .iter()
        .zip(ORACLE_Q_NPY_BYTES.iter())
        .enumerate()
    {
        assert_eq!(a, b, "q npy byte mismatch at {i}");
    }

    let phi_npy_bytes = std::fs::read(tmp.join("phi_000001.npy")).expect("phi npy must exist");
    assert_eq!(
        phi_npy_bytes.len(),
        ORACLE_PHI_NPY_BYTES.len(),
        "phi npy length mismatch"
    );
    for (i, (a, b)) in phi_npy_bytes
        .iter()
        .zip(ORACLE_PHI_NPY_BYTES.iter())
        .enumerate()
    {
        assert_eq!(a, b, "phi npy byte mismatch at {i}");
    }

    let vel_npy_bytes = std::fs::read(tmp.join("vel_000001.npy")).expect("vel npy must exist");
    assert_eq!(
        vel_npy_bytes.len(),
        ORACLE_VEL_NPY_BYTES.len(),
        "vel npy length mismatch"
    );
    for (i, (a, b)) in vel_npy_bytes
        .iter()
        .zip(ORACLE_VEL_NPY_BYTES.iter())
        .enumerate()
    {
        assert_eq!(a, b, "vel npy byte mismatch at {i}");
    }
}

